from pathlib import Path
import re
root=Path(__file__).parent
modules=['src/schema.js','src/core.js','src/controller.js','src/ui.js','preview.js']
code='\n'.join(re.sub(r'^export ', '', re.sub(r'^import .*?;\n','', (root/p).read_text(),flags=re.M),flags=re.M) for p in modules)
css=(root/'style.css').read_text()
html='''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>角色信息 · 互動預覽</title><style>'''+css+'''
body{margin:0;background:#0c1220;color:#edf0fa;font-family:system-ui,-apple-system,"Noto Sans TC",sans-serif}body:before{content:'';position:fixed;inset:0;background:radial-gradient(ellipse at 12% 10%,#504a7825,transparent 55%),radial-gradient(ellipse at 90% 75%,#a0865420,transparent 45%);pointer-events:none}.preview-wrap{max-width:1180px;margin:auto;padding:38px 38px 70px;position:relative}.preview-top{display:flex;justify-content:space-between;align-items:center;padding-bottom:23px;border-bottom:1px solid #a7b7da20}.preview-brand{font-size:14px;letter-spacing:.15em;color:#d8c291}.preview-tag{color:#95a1b9;font-size:11px}.preview-layout{display:grid;grid-template-columns:330px minmax(0,1fr);gap:60px;margin-top:52px;align-items:start}.preview-intro{position:sticky;top:40px}.preview-intro h1{font-size:40px;font-weight:500;line-height:1.5;letter-spacing:.03em;margin:14px 0 22px}.preview-intro h1 span{color:#d7bb83}.preview-intro p{color:#a1aec7;font-size:14px;line-height:1.9;max-width:300px}.preview-buttons{display:flex;flex-wrap:wrap;gap:9px;margin:27px 0 35px}.preview-notes{border-top:1px solid #a7b7da20;padding-top:22px;font-size:12px;color:#a9b5cd;line-height:2}.preview-notes strong{font-weight:500;color:#dcd2ed}.preview-demo{display:flex;gap:7px;flex-wrap:wrap;align-items:center;margin-bottom:8px}.preview-counter{font-size:11px;color:#7d8da8;margin-bottom:8px;letter-spacing:.04em}.preview-footer{font-size:11px;color:#70809b;margin-top:18px;line-height:1.8}#preview-stage{min-width:0}#preview-stage>.csb-panel{margin:0}.preview-buttons .csb-btn{padding:12px 18px}.preview-tag:before{content:'●';color:#c8b384;margin-right:8px;font-size:8px}@media(max-width:850px){.preview-layout{grid-template-columns:minmax(0,1fr);gap:25px;margin-top:28px}.preview-intro{position:static}.preview-intro h1{font-size:31px;margin:10px 0}.preview-intro p{max-width:none;font-size:13px}.preview-notes{display:none}.preview-buttons{margin:18px 0 8px}.preview-wrap{max-width:650px;padding:23px 18px 45px}.preview-top{padding-bottom:17px}.preview-tag{font-size:10px}.preview-brand{font-size:12px}.preview-footer{margin-top:14px}}@media(max-width:360px){.preview-wrap{padding-left:10px;padding-right:10px}.preview-intro h1{font-size:28px}.preview-top{gap:8px}.preview-tag{font-size:9px}}
</style></head><body><main class="preview-wrap csb"><header class="preview-top"><div class="preview-brand">◈ &nbsp; 角色信息</div><div class="preview-tag">互動預覽 · v1.1.0</div></header><div class="preview-layout"><aside class="preview-intro"><small class="csb-eyebrow">CHARACTERS. REMEMBERED.</small><h1>每一個角色，<br>都有<span>延續的故事。</span></h1><p>欄位由你定義，資料各自保存。角色暫時離場，記憶也不會離開。</p><div class="preview-buttons"><button class="csb-btn csb-primary" id="open-manager">開啟角色工坊</button><button class="csb-btn" id="open-fields">自訂欄位</button></div><div class="preview-notes"><strong>01 &nbsp; 一份共用模板</strong><br>身體特徵、身體部位、服裝、條狀狀態。<br><br><strong>02 &nbsp; 各自獨立的角色資料</strong><br>當前狀態與重要經歷，隨劇情延續。<br><br><strong>03 &nbsp; 自動生成狀態卡片</strong><br>展開姓名，查看每一項細節。</div></aside><section><div class="preview-counter" id="demo-count"></div><div class="preview-demo"><button class="csb-btn csb-small" id="simulate-rest">☕ 模擬休息</button><button class="csb-btn csb-small" id="simulate-leave">↗ 離場／重返</button><button class="csb-btn csb-small" id="reset-preview">重設預覽</button></div><div id="preview-stage"></div><p class="preview-footer">此頁使用示例角色與本機瀏覽器儲存，可實際編輯與匯出。模擬按鈕不會呼叫模型；安裝插件後才會接上酒館劇情。</p></section></div></main><script>'''+code.replace('</script','<\\/script')+'''</script></body></html>'''
(root/'Preview.html').write_text(html)
print('Preview.html',len(html.encode()),'bytes')
